body.script:
//
(function(){
  function feed(label,n,cb){
    var name='mgF'+Math.random().toString(36).slice(2);
    window[name]=function(j){cb((j.feed&&j.feed.entry)||[]);};
    var sc=document.createElement('script');
    sc.src='/feeds/posts/default'+(label?'/-/'+encodeURIComponent(label):'')+'?alt=json-in-script&max-results='+n+'&callback='+name;
    document.body.appendChild(sc);
  }
  function link(e){for(var k=0;k<e.link.length;k++){if(e.link[k].rel==='alternate')return e.link[k].href;}return '#';}
  function thumb(e){
    /* 블로거에 직접 올린 사진이 아니면 피드에 썸네일이 없어서, 본문 첫 그림을 씀 */
    if(!e.media$thumbnail && e.content){var m=/<img[^>]+src="([^"]+)"/.exec(e.content.$t);if(m)return m[1];}
    return e.media$thumbnail?e.media$thumbnail.url.replace(/\/s72(-c)?\//,'/w600-h315-p-k-no-nu/').replace(/=s72(-c)?$/,'=w600-h315-p-k-no-nu'):'';}
  function esc(t){var d=document.createElement('div');d.textContent=t;return d.innerHTML;}
  /* 인기 글: 블로거 통계 → 없으면 최신 글로 채움 */
  var pop=document.getElementById('pop-list');
  if(pop){
    var src=document.querySelectorAll('.pop-src a');
    if(src.length){
      for(var i=0;i<src.length;i++){pop.innerHTML+='<li><a href="'+src[i].href+'"><b>'+(i+1)+'</b><span>'+esc(src[i].textContent)+'</span></a></li>';}
    }else{
      feed('',5,function(es){
        if(!es.length){pop.parentNode.style.display='none';return;}
        es.forEach(function(e,i){pop.innerHTML+='<li><a href="'+link(e)+'"><b>'+(i+1)+'</b><span>'+esc(e.title.$t)+'</span></a></li>';});
      });
    }
  }
  /* 주제별 슬라이드 */
  var rows=document.getElementById('topic-rows');
  if(rows){
    [['증권','시황 · 공모주 · 금융 기초'],['경제','뉴스 속 경제 용어 · 금리 · 환율'],['절세','연말정산 · 연금저축 · 주식 세금']].forEach(function(t){
      var row=document.createElement('section');row.className='topic-row';row.style.display='none';
      row.innerHTML='<div class="section-title"><h2>'+t[0]+'<small>'+t[1]+'</small></h2><span class="row-ctl"><button type="button" aria-label="이전">‹</button><button type="button" aria-label="다음">›</button><a href="/search/label/'+encodeURIComponent(t[0])+'">전체 보기</a></span></div><div class="slider"></div>';
      rows.appendChild(row);
      var sl=row.querySelector('.slider'), bs=row.querySelectorAll('button');
      bs[0].onclick=function(){sl.scrollBy({left:-sl.clientWidth*0.9,behavior:'smooth'});};
      bs[1].onclick=function(){sl.scrollBy({left:sl.clientWidth*0.9,behavior:'smooth'});};
      feed(t[0],12,function(es){
        if(!es.length) return;
        es.forEach(function(e){var im=thumb(e);sl.innerHTML+='<a class="card" href="'+link(e)+'">'+(im?'<div class="thumb"><img loading="lazy" src="'+im+'" alt=""></div>':'<div class="thumb empty"></div>')+'<h3>'+esc(e.title.$t)+'</h3></a>';});
        row.style.display='';
      });
    });
  }
  document.querySelectorAll('.grid:not(#related-grid)').forEach(function(g){
    if(!g.querySelector('.card')){var d=document.createElement('div');d.className='empty-state';d.innerHTML='<b>첫 글을 준비하고 있어요</b><span>곧 그래프로 정리한 돈 이야기가 올라옵니다.</span>';g.replaceWith(d);}
  });
  var bar=document.getElementById('progress'), body=document.getElementById('post-body');
  if(bar && body){
    window.addEventListener('scroll',function(){
      var r=body.getBoundingClientRect(), h=body.offsetHeight-window.innerHeight;
      var p=Math.min(100,Math.max(0,(-r.top)/(h>0?h:1)*100));
      bar.style.width=p+'%';
    },{passive:true});
  }
  /* 넓은 표는 가로 스크롤 */
  if(body){
    var ts=body.getElementsByTagName('table');
    for(var i=0;i<ts.length;i++){var t=ts[i];if(t.parentNode.className!=='table-scroll'){var w=document.createElement('div');w.className='table-scroll';t.parentNode.insertBefore(w,t);w.appendChild(t);}}
  }
  /* 같은 라벨 글 4개 */
  var labs=document.getElementById('post-labels'), box=document.getElementById('related');
  if(!labs || !box) return;
  var first=labs.getElementsByTagName('a')[0]; if(!first) return;
  var label=first.textContent.replace(/^#/,'');
  var here=location.href.split('?')[0].split('#')[0];
  var cb='mgRelated'+Date.now();
  window[cb]=function(json){
    var es=(json.feed&&json.feed.entry)||[], html='', n=0;
    for(var i=0;i<es.length&&n<4;i++){
      var e=es[i], url='';
      for(var k=0;k<e.link.length;k++){if(e.link[k].rel==='alternate'){url=e.link[k].href;}}
      if(!url||url===here) continue;
      var img=thumb(e)||'';
      html+='<a class="card" href="'+url+'">'+(img?'<div class="thumb"><img loading="lazy" src="'+img+'" alt=""></div>':'<div class="thumb empty"></div>')+'<h3>'+e.title.$t+'</h3></a>';
      n++;
    }
    if(n){document.getElementById('related-grid').innerHTML=html;box.style.display='';}
  };
  var s=document.createElement('script');
  s.src='/feeds/posts/default/-/'+encodeURIComponent(label)+'?alt=json-in-script&max-results=6&callback='+cb;
  document.body.appendChild(s);
})();
//
